import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int E = sc.nextInt();
        int D = sc.nextInt();

        int result;
        if (E > D) {
            result = E + D;
        } else {
            result = 2 * (D - E);
        }

        System.out.println(result);
    }
}
```

